    # Older rows only stored the username; attach them to the account when it still exists.
    AuditEvent = apps.get_model("portal", "AuditEvent")
    app_label, model_name = settings.AUTH_USER_MODEL.split(".")
    User = apps.get_model(app_label, model_name)
    username_field = getattr(User, "USERNAME_FIELD", "username")
    actors = AuditEvent.objects.filter(user__isnull=True).exclude(actor="").values_list("actor", flat=True).distinct()
